CREATE TABLE png_document (id INTEGER PRIMARY KEY CHECK(id=1), schema TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('literal','native')));
CREATE TABLE png_literal_octet (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES png_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
CREATE TABLE png_chunk (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES png_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), kind TEXT NOT NULL);
CREATE TABLE png_ihdr (id INTEGER PRIMARY KEY REFERENCES png_chunk(id), width INTEGER NOT NULL CHECK(width BETWEEN 1 AND 4294967295), height INTEGER NOT NULL CHECK(height BETWEEN 1 AND 4294967295), bit_depth INTEGER NOT NULL CHECK(bit_depth IN (1,2,4,8,16)), color_type INTEGER NOT NULL CHECK(color_type IN (0,2,3,4,6)), compression INTEGER NOT NULL CHECK(compression=0), filter INTEGER NOT NULL CHECK(filter=0), interlace INTEGER NOT NULL CHECK(interlace IN (0,1)));
CREATE TABLE png_palette (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES png_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), red INTEGER NOT NULL CHECK(red BETWEEN 0 AND 255), green INTEGER NOT NULL CHECK(green BETWEEN 0 AND 255), blue INTEGER NOT NULL CHECK(blue BETWEEN 0 AND 255));
CREATE TABLE png_transparency (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES png_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), sample INTEGER NOT NULL CHECK(sample BETWEEN 0 AND 65535));
CREATE TABLE png_background (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES png_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), sample INTEGER NOT NULL CHECK(sample BETWEEN 0 AND 65535));
CREATE TABLE png_gamma (id INTEGER PRIMARY KEY REFERENCES png_chunk(id), value INTEGER NOT NULL CHECK(value BETWEEN 1 AND 4294967295));
CREATE TABLE png_chromaticity (id INTEGER PRIMARY KEY REFERENCES png_chunk(id), white_x INTEGER NOT NULL CHECK(white_x BETWEEN 0 AND 4294967295), white_y INTEGER NOT NULL CHECK(white_y BETWEEN 0 AND 4294967295), red_x INTEGER NOT NULL CHECK(red_x BETWEEN 0 AND 4294967295), red_y INTEGER NOT NULL CHECK(red_y BETWEEN 0 AND 4294967295), green_x INTEGER NOT NULL CHECK(green_x BETWEEN 0 AND 4294967295), green_y INTEGER NOT NULL CHECK(green_y BETWEEN 0 AND 4294967295), blue_x INTEGER NOT NULL CHECK(blue_x BETWEEN 0 AND 4294967295), blue_y INTEGER NOT NULL CHECK(blue_y BETWEEN 0 AND 4294967295));
CREATE TABLE png_srgb (id INTEGER PRIMARY KEY REFERENCES png_chunk(id), intent INTEGER NOT NULL CHECK(intent BETWEEN 0 AND 3));
CREATE TABLE png_physical (id INTEGER PRIMARY KEY REFERENCES png_chunk(id), x INTEGER NOT NULL CHECK(x BETWEEN 0 AND 4294967295), y INTEGER NOT NULL CHECK(y BETWEEN 0 AND 4294967295), unit INTEGER NOT NULL CHECK(unit IN (0,1)));
CREATE TABLE png_time (id INTEGER PRIMARY KEY REFERENCES png_chunk(id), year INTEGER NOT NULL CHECK(year BETWEEN 0 AND 65535), month INTEGER NOT NULL CHECK(month BETWEEN 0 AND 255), day INTEGER NOT NULL CHECK(day BETWEEN 0 AND 255), hour INTEGER NOT NULL CHECK(hour BETWEEN 0 AND 255), minute INTEGER NOT NULL CHECK(minute BETWEEN 0 AND 255), second INTEGER NOT NULL CHECK(second BETWEEN 0 AND 255));
CREATE TABLE png_stream (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES png_document(id), cmf INTEGER NOT NULL CHECK(cmf BETWEEN 0 AND 255), flg INTEGER NOT NULL CHECK(flg BETWEEN 0 AND 255), adler INTEGER NOT NULL CHECK(adler BETWEEN 0 AND 4294967295), padding INTEGER NOT NULL CHECK(padding BETWEEN 0 AND 127), padding_bits INTEGER NOT NULL CHECK(padding_bits BETWEEN 0 AND 7));
CREATE TABLE png_text (id INTEGER PRIMARY KEY REFERENCES png_chunk(id), keyword TEXT NOT NULL, value TEXT NOT NULL, language TEXT NOT NULL, translated TEXT NOT NULL, compressed INTEGER NOT NULL CHECK(compressed IN (0,1)), stream_id INTEGER REFERENCES png_stream(id), CHECK((compressed=0 AND stream_id IS NULL) OR (compressed=1 AND stream_id IS NOT NULL)));
CREATE TABLE png_unknown_octet (id INTEGER PRIMARY KEY, chunk_id INTEGER NOT NULL REFERENCES png_chunk(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
CREATE TABLE png_idat (id INTEGER PRIMARY KEY REFERENCES png_chunk(id), stream_id INTEGER NOT NULL REFERENCES png_stream(id), length INTEGER NOT NULL CHECK(length>=0));
CREATE TABLE png_deflate_block (id INTEGER PRIMARY KEY, stream_id INTEGER NOT NULL REFERENCES png_stream(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), final INTEGER NOT NULL CHECK(final IN (0,1)), kind INTEGER NOT NULL CHECK(kind IN (0,1,2)), alignment INTEGER NOT NULL CHECK(alignment BETWEEN 0 AND 127), hlit INTEGER NOT NULL CHECK(hlit BETWEEN 0 AND 286), hdist INTEGER NOT NULL CHECK(hdist BETWEEN 0 AND 32), hclen INTEGER NOT NULL CHECK(hclen BETWEEN 0 AND 19));
CREATE TABLE png_deflate_code (id INTEGER PRIMARY KEY, block_id INTEGER NOT NULL REFERENCES png_deflate_block(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), length INTEGER NOT NULL CHECK(length BETWEEN 0 AND 7));
CREATE TABLE png_deflate_length (id INTEGER PRIMARY KEY, block_id INTEGER NOT NULL REFERENCES png_deflate_block(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), symbol INTEGER NOT NULL CHECK(symbol BETWEEN 0 AND 18), extra INTEGER NOT NULL CHECK(extra BETWEEN 0 AND 127));
CREATE TABLE png_deflate_token (id INTEGER PRIMARY KEY, block_id INTEGER NOT NULL REFERENCES png_deflate_block(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), symbol INTEGER NOT NULL CHECK(symbol BETWEEN 0 AND 285), extra INTEGER NOT NULL CHECK(extra BETWEEN 0 AND 31), distance_symbol INTEGER CHECK(distance_symbol BETWEEN 0 AND 29), distance_extra INTEGER CHECK(distance_extra BETWEEN 0 AND 8191), CHECK((symbol<=256 AND distance_symbol IS NULL AND distance_extra IS NULL) OR (symbol>256 AND distance_symbol IS NOT NULL AND distance_extra IS NOT NULL)));
CREATE TABLE png_scanline (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES png_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), pass INTEGER NOT NULL CHECK(pass BETWEEN 0 AND 6), row INTEGER NOT NULL CHECK(row>=0), width INTEGER NOT NULL CHECK(width>=1), channels INTEGER NOT NULL CHECK(channels BETWEEN 1 AND 4), bit_depth INTEGER NOT NULL CHECK(bit_depth IN (1,2,4,8,16)), filter INTEGER NOT NULL CHECK(filter BETWEEN 0 AND 4));
CREATE TABLE png_sample (id INTEGER PRIMARY KEY, scanline_id INTEGER NOT NULL REFERENCES png_scanline(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 65535));
CREATE TABLE png_packed_remainder (id INTEGER PRIMARY KEY REFERENCES png_scanline(id), bit_count INTEGER NOT NULL CHECK(bit_count BETWEEN 1 AND 7), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 127));
CREATE TABLE png_inflated_tail (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES png_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
